css:
  :root{
    color-scheme: light;
    --page:#f6f6f2;
    --surface:#fdfdfc;
    --ink:#111110;
    --ink-2:#4f4e49;
    --ink-3:#6b6a64;
    --hairline:rgba(17,17,16,.10);
    --hairline-strong:rgba(17,17,16,.17);
    --grid:#e6e5df;
    --baseline:#c9c8c0;
    --accent:#2a78d6;
    --good:#0d6b3a;
    --good-wash:#e7f2e9;
    --bad:#b3261e;
    --bad-wash:#fbeceb;
    --shadow:0 1px 2px rgba(17,17,16,.035);
    --font:-apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, "Helvetica Neue", Arial, sans-serif;
    --mono:ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  }
  *,*::before,*::after{box-sizing:border-box}
  html{-webkit-text-size-adjust:100%}
  body{
    margin:0;
    background:var(--page);
    color:var(--ink);
    font-family:var(--font);
    font-size:14px;
    line-height:1.45;
    -webkit-font-smoothing:antialiased;
    text-rendering:optimizeLegibility;
  }
  button{font:inherit;color:inherit}
  a{color:inherit;text-decoration:none}
  h1,h2,p{margin:0}
  :focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
  .sr-only{
    position:absolute;width:1px;height:1px;padding:0;margin:-1px;
    overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;
  }
  .skip{
    position:absolute;left:12px;top:-60px;z-index:100;
    padding:8px 12px;border:1px solid var(--hairline-strong);border-radius:8px;
    background:var(--surface);font-size:12px;font-weight:500;
    transition:top .12s ease;
  }
  .skip:focus{top:10px}

  /* Top bar */
  .topbar{
    position:sticky;top:0;z-index:30;
    height:56px;
    display:flex;align-items:center;justify-content:space-between;gap:12px;
    padding:0 20px;
    background:rgba(253,253,252,.92);
    -webkit-backdrop-filter:saturate(1.4) blur(10px);
    backdrop-filter:saturate(1.4) blur(10px);
    border-bottom:1px solid var(--hairline);
  }
  .brand{display:flex;align-items:center;gap:9px;min-width:0}
  .brand-mark{display:flex;flex:0 0 auto;border-radius:7px;box-shadow:0 1px 2px rgba(17,17,16,.18)}
  .brand-name{font-size:15px;font-weight:650;letter-spacing:-.012em;white-space:nowrap}
  .top-actions{display:flex;align-items:center;gap:10px;min-width:0}
  .range{
    position:relative;
    display:inline-flex;align-items:center;gap:7px;
    height:36px;padding:0 11px;
    border:1px solid var(--hairline);border-radius:8px;
    background:var(--surface);
    color:var(--ink-2);font-size:12px;font-weight:500;white-space:nowrap;
    cursor:pointer;
    transition:background .12s ease,border-color .12s ease;
  }
  .range:hover{background:#f4f4f0;border-color:var(--hairline-strong)}
  .range svg{flex:0 0 auto;color:var(--ink-3)}
  .range::after{content:"";position:absolute;inset:-4px;border-radius:10px}
  .top-div{width:1px;height:20px;flex:0 0 auto;background:var(--hairline)}
  .avatar{
    position:relative;
    width:34px;height:34px;flex:0 0 auto;
    display:grid;place-items:center;
    border:1px solid rgba(17,17,16,.12);border-radius:50%;
    background:linear-gradient(145deg,#dde9f9 0%,#bdd4ef 100%);
    color:#1e4f8c;font-size:11px;font-weight:650;letter-spacing:.02em;
    cursor:pointer;
  }
  .avatar:hover{background:linear-gradient(145deg,#d4e3f8 0%,#b2cced 100%)}
  .avatar::after{content:"";position:absolute;inset:-6px;border-radius:50%}

  /* Shell + navigation */
  .shell{display:flex;align-items:flex-start}
  .sidebar{
    position:sticky;top:56px;
    flex:0 0 216px;width:216px;height:calc(100vh - 56px);
    padding:18px 12px;
    border-right:1px solid var(--hairline);
    background:var(--surface);
  }
  .nav{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}
  .nav a{
    display:flex;align-items:center;gap:10px;
    height:40px;padding:0 10px;border-radius:7px;
    color:var(--ink-2);font-size:13px;font-weight:500;
    transition:background .12s ease,color .12s ease;
  }
  .nav a:hover{background:rgba(17,17,16,.045);color:var(--ink)}
  .nav a svg{flex:0 0 auto;color:var(--ink-3)}
  .nav a[aria-current="page"]{background:#ebeae4;color:var(--ink);font-weight:600}
  .nav a[aria-current="page"] svg{color:var(--accent)}

  /* Main */
  main{flex:1 1 auto;min-width:0;padding:24px}
  main:focus{outline:none}
  .page-head{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:18px}
  h1{font-size:20px;font-weight:650;letter-spacing:-.022em;line-height:1.2}
  .page-sub{font-size:12.5px;color:var(--ink-3);white-space:nowrap}

  /* KPI cards */
  .kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}
  .kpi{
    min-width:0;
    padding:15px 16px 14px;
    background:var(--surface);
    border:1px solid var(--hairline);border-radius:10px;
    box-shadow:var(--shadow);
  }
  .kpi-label{font-size:12px;font-weight:500;color:var(--ink-2)}
  .kpi-value{
    margin-top:7px;
    font-size:26px;font-weight:600;letter-spacing:-.028em;line-height:1.15;
    white-space:nowrap;
  }
  .kpi-delta{
    display:inline-flex;align-items:center;
    margin-top:8px;padding:2px 7px;
    border-radius:999px;
    font-size:11.5px;font-weight:500;
    font-variant-numeric:tabular-nums;
  }
  .is-good{color:var(--good);background:var(--good-wash)}
  .is-bad{color:var(--bad);background:var(--bad-wash)}

  /* Panels */
  .lower{
    display:grid;
    grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);
    gap:16px;align-items:stretch;
  }
  .panel{
    display:flex;flex-direction:column;min-width:0;
    background:var(--surface);
    border:1px solid var(--hairline);border-radius:10px;
    box-shadow:var(--shadow);
  }
  .panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:16px 18px 10px}
  .panel-title{font-size:13.5px;font-weight:600;letter-spacing:-.006em}
  .panel-sub{margin-top:2px;font-size:11.5px;color:var(--ink-3)}

  /* Chart */
  .chart-wrap{
    position:relative;
    height:300px;
    margin:2px 10px 0 6px;
    outline:none;
    touch-action:pan-y;
  }
  .chart-wrap:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px}
  .chart-wrap svg{display:block;overflow:visible}
  .chart-tip{
    position:absolute;z-index:5;pointer-events:none;
    display:flex;align-items:baseline;gap:6px;
    padding:5px 8px;
    border-radius:6px;
    background:#171715;color:#fff;
    font-size:11px;line-height:1.3;white-space:nowrap;
    box-shadow:0 8px 20px -10px rgba(0,0,0,.55);
  }
  .chart-tip[hidden]{display:none}
  .chart-tip strong{font-size:12px;font-weight:600;font-variant-numeric:tabular-nums}
  .chart-tip span{color:#bdbab1}

  .chart-data{margin-top:auto;border-top:1px solid var(--hairline)}
  .chart-data summary{
    list-style:none;cursor:pointer;user-select:none;
    display:flex;align-items:center;gap:7px;
    padding:9px 18px;
    font-size:11.5px;color:var(--ink-3);
  }
  .chart-data summary::-webkit-details-marker{display:none}
  .chart-data summary::after{
    content:"";margin-left:auto;
    width:6px;height:6px;
    border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;
    transform:rotate(45deg) translateY(-1px);
    transition:transform .15s ease;
  }
  .chart-data[open] summary::after{transform:rotate(-135deg) translateY(-1px)}
  .chart-data summary:hover{color:var(--ink-2)}
  .data-table{width:100%;border-collapse:collapse;font-size:11.5px;margin-bottom:10px}
  .data-table caption{text-align:left;padding:0 18px 6px;font-size:10.5px;color:var(--ink-3)}
  .data-table th,.data-table td{padding:4px 8px;border-bottom:1px solid var(--hairline)}
  .data-table th:first-child,.data-table td:first-child{padding-left:18px}
  .data-table th:last-child,.data-table td:last-child{padding-right:18px}
  .data-table th{font-size:10.5px;font-weight:500;color:var(--ink-3);text-align:left}
  .data-table td:last-child,.data-table th:last-child{text-align:right;font-variant-numeric:tabular-nums}
  .data-table tr:last-child td{border-bottom:0}
  .data-table td{color:var(--ink-2)}

  /* Events table */
  .table-panel{padding-bottom:0}
  .events{
    width:100%;border-collapse:collapse;table-layout:fixed;
    font-size:12.5px;
  }
  .events col.c-event{width:auto}
  .events col.c-count{width:66px}
  .events col.c-users{width:60px}
  .events col.c-trend{width:52px}
  .events th{
    padding:8px 6px;
    border-top:1px solid var(--hairline);border-bottom:1px solid var(--hairline);
    font-size:11px;font-weight:500;color:var(--ink-3);text-align:left;
  }
  .events th:first-child,.events td:first-child{padding-left:18px}
  .events th:last-child,.events td:last-child{padding-right:18px;text-align:right}
  .events th.num,.events td.num{text-align:right;font-variant-numeric:tabular-nums}
  .events td{
    height:49px;padding:0 6px;
    border-bottom:1px solid var(--hairline);
    white-space:nowrap;vertical-align:middle;
  }
  .events tbody tr:last-child td{border-bottom:0}
  .events tbody tr{transition:background .1s ease}
  .events tbody tr:hover{background:#f6f6f2}
  .event-name{
    overflow:hidden;text-overflow:ellipsis;
    font-family:var(--mono);font-size:12px;letter-spacing:-.01em;
    color:var(--ink);
  }
  .event-count{font-weight:500;color:var(--ink)}
  .event-users{color:var(--ink-2)}
  .event-trend{color:var(--ink-2);font-size:13px}
  .table-foot{
    margin-top:auto;
    padding:10px 18px 14px;
    font-size:11px;color:var(--ink-3);text-align:right;
  }

  @media (max-width:1199px){
    .lower{grid-template-columns:minmax(0,1fr)}
    .chart-wrap{height:280px}
  }
  @media (max-width:1039px){
    .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  }
  @media (max-width:820px){
    .shell{display:block}
    .sidebar{
      position:static;width:auto;height:auto;flex:none;
      padding:0;overflow:visible;
      background:var(--surface);
      border-right:0;border-bottom:1px solid var(--hairline);
    }
    .nav{display:grid;grid-template-columns:repeat(4,1fr);gap:0;padding:0 8px}
    .nav a{
      height:46px;justify-content:center;gap:6px;
      padding:0 4px;border-radius:0;
      border-bottom:2px solid transparent;
      font-size:11.5px;
    }
    .nav a:hover{background:transparent;color:var(--ink)}
    .nav a[aria-current="page"]{
      background:transparent;color:var(--ink);
      border-bottom-color:var(--accent);
    }
    .nav a svg{width:15px;height:15px}
    main{padding:20px 16px 32px}
    .chart-wrap{height:250px}
  }
  @media (max-width:560px){
    .page-head{margin-bottom:14px}
    .kpis{gap:10px;margin-bottom:14px}
    .kpi{padding:13px 13px 12px}
    .kpi-label{font-size:11.5px}
    .kpi-value{font-size:23px;margin-top:5px}
    .kpi-delta{font-size:11px;margin-top:6px;padding:2px 6px}
    .lower{gap:12px}
    .panel-head{padding:14px 14px 8px}
    .chart-wrap{height:206px;margin:0 4px 0 2px}
    .chart-data summary{padding:9px 14px}
    .data-table th:first-child,.data-table td:first-child{padding-left:14px}
    .data-table th:last-child,.data-table td:last-child{padding-right:14px}
    .events col.c-count{width:56px}
    .events col.c-users{width:50px}
    .events col.c-trend{width:44px}
    .events th{font-size:10.5px;padding:7px 4px}
    .events td{height:47px;padding:0 4px;font-size:11.5px}
    .events th:first-child,.events td:first-child{padding-left:14px}
    .events th:last-child,.events td:last-child{padding-right:12px}
    .event-name{font-size:11.5px}
    .table-foot{padding:9px 14px 13px}
  }
  @media (max-width:480px){
    .topbar{padding:0 14px;gap:8px}
    .brand{gap:8px}
    .brand-mark svg{width:22px;height:22px}
    .brand-name{font-size:14px}
    .top-actions{gap:8px}
    .range{height:36px;padding:0 9px;gap:6px;font-size:11.5px}
    .avatar{width:32px;height:32px;font-size:10.5px}
    main{padding:16px 14px 28px}
    h1{font-size:19px}
    .page-sub{font-size:12px}
  }
  @media (max-width:350px){
    .range svg{display:none}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{transition-duration:.01ms !important;animation-duration:.01ms !important}
  }
cursor:crosshair
